import "core-js/modules/es.array.push.js";
/* eslint-disable */
import AssignAgent from "@/components/CRM/Popups/AssignAgent.vue";
import CampaignDetailsView from "@/components/CRM/Popups/CampaignDetailsView.vue";
import SnackBar from "@/components/SnackBar.vue";
// import { list_campaigns_users } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {},
  components: {
    AssignAgent,
    SnackBar,
    CampaignDetailsView
  },
  data() {
    return {
      height: 0,
      tableData: [],
      headers: [{
        text: "Name",
        value: "sales_person_name",
        sortable: false
      }, {
        text: "Email",
        value: "sales_email_id",
        sortable: false
      }],
      tableLoading: false,
      pagination: {
        pageStart: 1,
        page: 1,
        rowsPerPage: 20,
        itemsPerPage: 20
      },
      fixed: false,
      toggle_exclusive: "campaignInfo",
      componentCheck: 0,
      addAgentDialog: false,
      SnackBarComponent: {}
    };
  },
  watch: {
    toggle_exclusive() {
      if (this.toggle_exclusive == "agents") {
        this.fetch_agents_list();
      }
    }
    // nextToken() {
    //   this.updatePagination();
    // },
  },
  created() {
    this.height = window.innerHeight - 250;
  },
  methods: {
    back_action() {
      this.$store.commit("Setproductitems", {});
      this.$router.push({
        name: "CrmAdmins",
        params: {
          formMethod: "campaigns"
        }
      });
    },
    async fetch_agents_list() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_campaigns_users, {
          input: {
            organization_id: data.organization.organization_id,
            campaign_id: this.$store.getters.Getproductitems.campaign_id,
            limit: 100,
            nextToken: null
          }
        }));
        this.tableLoading = false;
        var response = result.data.list_campaigns_users;
        this.tableData = response.items;
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    assign_agents() {
      this.componentCheck = 1;
      this.addAgentDialog = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addAgentDialog = false;
      this.fetch_agents_list();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
